type Lang = 'en' | 'hi'
type Ctx = { lang: Lang; setLang: (l: Lang) => void; t: (k: string, v?: Record<string, string | number>) => string; tc: (code: string) => string; tf: (k: string, fallback: string) => string }
const I18n = createContext<Ctx>(null as unknown as Ctx)
export const useI18n = () => useContext(I18n)

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(() => { try { return localStorage.getItem('griha_lang') === 'hi' ? 'hi' : 'en' } catch { return 'en' } })
  useEffect(() => { document.documentElement.lang = lang }, [lang])
  const value = useMemo<Ctx>(() => ({
    lang,
    setLang: l => { setLangState(l); try { localStorage.setItem('griha_lang', l) } catch { /* ignore */ } },
    t: (k, v) => {
      const raw = (lang === 'hi' ? hi[k] : undefined) ?? en[k] ?? k
      return v ? raw.replace(/\{(\w+)\}/g, (_, n) => String(v[n] ?? `{${n}}`)) : raw
    },
    tc: code => HI_CODES[code] ?? '',
    tf: (k, fb) => (lang === 'hi' ? hi[k] : undefined) ?? fb,
  }), [lang])
  return <I18n.Provider value={value}>{children}</I18n.Provider>
}

/** Localised one-line verdict built from structured decision data (the engine's own sentence stays English). */
export function headlineOf(d: any, t: Ctx['t'], tc: Ctx['tc'], lang: Lang): string {
  if (lang !== 'hi') return d.headline
  const inr = (n: number) => '₹' + Math.round(n).toLocaleString('en-IN')
  if (d.outcome === 'APPROVE' && d.offer) return t('hl.approve', { amt: inr(d.offer.amount), rate: d.offer.rate_pct, yrs: d.offer.tenure_months / 12 }) + (d.offer.reduced ? t('hl.reduced', { req: inr(d.offer.requested) }) : '')
  const code = d.reasons.find((r: any) => ['policy', 'fraud', 'property', 'data'].includes(r.kind))?.code
  const why = code ? tc(code) : ''
  const lead = d.outcome === 'REFER' ? t('hl.refer', { q: t('queue.' + d.refer_queue) }) : t('hl.reject')
  return why ? lead + t('hl.then', { why }) : lead
}
